package mod.cdv.tnpc.tactical;
import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;
public final class SocialR {
 static final Map<String,Class<?>> types=new ConcurrentHashMap<>();static final ClassValue<Map<String,Field>> fields=new ClassValue<>(){protected Map<String,Field> computeValue(Class<?> c){return new ConcurrentHashMap<>();}};
 static final ClassValue<Map<String,Method>> methods=new ClassValue<>(){protected Map<String,Method> computeValue(Class<?> c){return new ConcurrentHashMap<>();}};
 public static Class<?> type(String s){return types.computeIfAbsent(s,k->{try{return Class.forName(k);}catch(Exception e){throw new IllegalStateException(e);}});}
 static Class<?> box(Class<?> c){if(c==byte.class)return Byte.class;if(c==short.class)return Short.class;if(c==char.class)return Character.class;if(c==int.class)return Integer.class;if(c==boolean.class)return Boolean.class;if(c==double.class)return Double.class;if(c==float.class)return Float.class;if(c==long.class)return Long.class;return c;}
 public static Object call(Object o,String n,Object...a){Class<?> c=o instanceof Class?(Class<?>)o:o.getClass();String key=n+Arrays.toString(Arrays.stream(a).map(x->x==null?Void.class:x.getClass()).toArray());Method m=methods.get(c).computeIfAbsent(key,k->{for(Class<?> t=c;t!=null;t=t.getSuperclass())for(Method v:t.getDeclaredMethods()){if(!v.getName().equals(n)||v.getParameterCount()!=a.length)continue;boolean ok=true;Class<?>[] p=v.getParameterTypes();for(int i=0;i<p.length;i++)if(a[i]!=null&&!box(p[i]).isInstance(a[i]))ok=false;if(ok){v.setAccessible(true);return v;}}for(Method v:c.getMethods()){if(!v.getName().equals(n)||v.getParameterCount()!=a.length)continue;boolean ok=true;Class<?>[] p=v.getParameterTypes();for(int i=0;i<p.length;i++)if(a[i]!=null&&!box(p[i]).isInstance(a[i]))ok=false;if(ok){v.setAccessible(true);return v;}}throw new IllegalStateException(c+"."+n);});try{return m.invoke(o instanceof Class?null:o,a);}catch(Exception e){throw new IllegalStateException(c+"."+n,e);}}
 public static Object get(Object o,String n){Class<?> c=o instanceof Class?(Class<?>)o:o.getClass();Field f=fields.get(c).computeIfAbsent(n,k->{for(Class<?> t=c;t!=null;t=t.getSuperclass())try{Field v=t.getDeclaredField(k);v.setAccessible(true);return v;}catch(NoSuchFieldException e){}throw new IllegalStateException(c+"."+n);});try{return f.get(o instanceof Class?null:o);}catch(Exception e){throw new IllegalStateException(e);}}
 public static void set(Object o,String n,Object v){Class<?> c=o.getClass();for(Class<?> t=c;t!=null;t=t.getSuperclass())try{Field f=t.getDeclaredField(n);f.setAccessible(true);f.set(o,v);return;}catch(NoSuchFieldException missing){}catch(IllegalAccessException e){throw new IllegalStateException(e);}throw new IllegalStateException(c+"."+n);}
 public static Object make(String name,Object...a){for(Constructor<?> v:type(name).getConstructors()){if(v.getParameterCount()!=a.length)continue;boolean ok=true;Class<?>[] p=v.getParameterTypes();for(int i=0;i<p.length;i++)if(a[i]!=null&&!box(p[i]).isInstance(a[i]))ok=false;if(ok)try{return v.newInstance(a);}catch(Exception e){throw new IllegalStateException(e);}}throw new IllegalStateException(name);}
}
